svg.script:

function loadFromLocalStorage() {
  const savedData = localStorage.getItem('svgLocalStorageDemo');
  const outputEl = document.getElementById('svgOutput');
  if (savedData) {
    outputEl.textContent = "Opgehaald uit LocalStorage: " + savedData;
  } else {
    outputEl.textContent = "Geen data gevonden in LocalStorage.";
  }
}

function saveToLocalStorage() {
  const inputEl = document.getElementById('svgInput');
  const val = inputEl.value;
  if (val.trim() !== "") {
    localStorage.setItem('svgLocalStorageDemo', val);
    loadFromLocalStorage();
  }
}

// Laad data automatisch bij openen
window.addEventListener('DOMContentLoaded', loadFromLocalStorage);
